const temas = $('Parsear Sheet Completo').first().json.temas || [];
const metricas = $('Parsear Sheet Completo').first().json.metricas || [];
const rechazos = $('Parsear Sheet Completo').first().json.rechazos || [];

const ahora = Date.now();
const dias21 = 21 * 24 * 60 * 60 * 1000;

const candidatos = temas.filter(t => {
  const est = (t.estado || '').toLowerCase().trim();
  if (est === 'pendiente' || est === 'esperando_foto' || est === '') return true;
  if (est === 'disponible') return true;
  if (est === 'publicado' && t.fecha_pub) {
    return (ahora - new Date(t.fecha_pub).getTime()) > dias21;
  }
  return false;
});

if (candidatos.length === 0) throw new Error('No hay temas disponibles.');

const erPorArea = {};
metricas.forEach(m => {
  const area = m.area || m.tema || '';
  const er = parseFloat(m.engagement_rate) || 0;
  if (!erPorArea[area]) erPorArea[area] = [];
  erPorArea[area].push(er);
});

const todosER = metricas.map(m => parseFloat(m.engagement_rate) || 0).filter(e => e > 0).sort((a,b) => a-b);
const p25 = todosER[Math.floor(todosER.length * 0.25)] || 0.0097;
const p75 = todosER[Math.floor(todosER.length * 0.75)] || 0.0181;

const hace14dias = ahora - 14 * 24 * 60 * 60 * 1000;
const rechazosRecientes = {};
rechazos.forEach(r => {
  const fecha = new Date(r.fecha || 0).getTime();
  if (fecha > hace14dias) {
    rechazosRecientes[r.tema_id] = (rechazosRecientes[r.tema_id] || 0) + 1;
  }
});

const hoy = new Date();
const ultimaPubPorArea = {};
temas.filter(t => t.fecha_pub).forEach(t => {
  const area = t.area || '';
  const fecha = new Date(t.fecha_pub);
  if (!ultimaPubPorArea[area] || fecha > ultimaPubPorArea[area]) ultimaPubPorArea[area] = fecha;
});

const diaSemana = hoy.getDay();
const tonosDia = { 1: 'reflexivo', 3: 'herramienta', 5: 'provocador' };
const tonoContexto = tonosDia[diaSemana] || 'directo';

candidatos.forEach(t => {
  const est = (t.estado || '').toLowerCase().trim();
  let score = parseFloat(t.score || 1);

  // Penalización por repetición
  const veces = parseInt(t.veces_publicado || 0);
  score *= (1 - Math.min(veces * 0.20, 0.60));

  // Boost por tiempo sin publicarse
  if (t.fecha_pub) {
    const diasDesde = (ahora - new Date(t.fecha_pub).getTime()) / (1000*60*60*24);
    score *= (1 + Math.min((diasDesde / 7) * 0.05, 0.40));
  } else {
    score *= 1.5;
  }

  // Engagement del área
  const erArea = erPorArea[t.area || ''] || [];
  if (erArea.length > 0) {
    const erPromedioArea = erArea.reduce((a,b) => a+b,0) / erArea.length;
    if (erPromedioArea > p75) score *= 1.3;
    else if (erPromedioArea < p25) score *= 0.8;
  }

  // Rechazos recientes
  score *= Math.pow(0.75, rechazosRecientes[t.id] || 0);

  // Tono del día — boost menor para no dominar
  if ((t.tono || '').toLowerCase() === tonoContexto) score *= 1.05;

  // ── Aleatoriedad más fuerte: ±30% usando Math.random() puro ──────
  // Suficiente para romper empates entre temas con score similar
  const rand = Math.random();
  score *= (0.85 + rand * 0.45); // rango: 0.85 a 1.30

  // Penalizar temas con fecha_propuesto reciente (aunque no se hayan publicado)
  if (t.fecha_propuesto) {
    const diasPropuesto = (ahora - new Date(t.fecha_propuesto).getTime()) / (1000*60*60*24);
    if (diasPropuesto < 7) score *= 0.4; // fuerte penalización si fue propuesto esta semana
  }

  t.score_final = Math.round(score * 100) / 100;
  t.tono_contexto = tonoContexto;
  t.es_repeticion = veces > 0;
});

// Elegir entre top 3 con weighted random para más variedad
const ordenados = candidatos.sort((a,b) => b.score_final - a.score_final);
const top3 = ordenados.slice(0, Math.min(3, ordenados.length));

// Weighted random sobre top 3
const totalScore = top3.reduce((a,t) => a + t.score_final, 0);
let rand = Math.random() * totalScore;
let ganador = top3[0];
for (const t of top3) {
  rand -= t.score_final;
  if (rand <= 0) { ganador = t; break; }
}

const erTotal = todosER.reduce((a,b) => a+b, 0);
const erPromedio = todosER.length > 0 ? erTotal/todosER.length : 0.0139;

return [{ json: {
  ...ganador,
  tema: ganador.tema_nombre || ganador.tema,
  tema_nombre: ganador.tema_nombre || ganador.tema,
  tipo_post: ganador.tipo_post || 'reflexión',
  nivel_profundidad: ganador.nivel_profundidad || 'avanzado',
  tono: ganador.tono || tonoContexto,
  objetivo: ganador.objetivo || 'posicionamiento',
  er_promedio_dinamico: erPromedio,
  er_p25: p25,
  er_p75: p75,
  rechazos_recientes: rechazosRecientes
}}];

const data = $json;
const results = data.results || [];

if (data.errors) {
