const autor_usuario = foto.user?.username || '';
const imagen_credit = autor_nombre
  ? `${autor_nombre} (@${autor_usuario}) — Unsplash`
  : 'Unsplash';
const foto_id = (imagen_url.match(/photo-([a-zA-Z0-9]+-[a-zA-Z0-9]+)/) || [])[1] || '';

return [{ json: { imagen_url, imagen_credit, foto_id } }];

const postData = $('Validar Calidad Post').first().json;
