const hace30dias = Date.now() - 30 * 24 * 60 * 60 * 1000;
const conPostId = items.filter(i => {
  const post_id = i.json.post_id || '';
  const fecha = new Date(i.json.fecha_pub || 0).getTime();
  return post_id && post_id !== '' && fecha > hace30dias;
});
if (conPostId.length === 0) throw new Error('No hay posts publicados en los últimos 30 días con post_id');
return conPostId;

const posts_publicados = $('Filtrar con Post ID').all().map(i => i.json);
const apify_results = items.map(i => i.json);

// Extrae la parte numérica del ID (normaliza URNs de distintos formatos)
function extractNumericId(s) {
  if (!s) return '';
  const m = String(s).match(/(\d{10,})/);
  return m ? m[1] : String(s);
}

const metricas = [];
for (const pub of posts_publicados) {
  const post_id = pub.post_id || '';
  const post_id_num = extractNumericId(post_id);
  const apify_post = apify_results.find(p => {
    const apify_id_raw = p.postId || p.id || p.shareUrn || p.activityUrn || '';
    const apify_id_num = extractNumericId(apify_id_raw);
    if (!apify_id_num || !post_id_num) return false;
    return apify_id_num === post_id_num || 
           apify_id_num.includes(post_id_num) || 
           post_id_num.includes(apify_id_num);
  });
  if (!apify_post) continue;

  let likes = 0;
  if (apify_post.reactionTypeCounts && Array.isArray(apify_post.reactionTypeCounts)) {
    likes = apify_post.reactionTypeCounts.reduce((s, r) => s + (r.count || 0), 0);
  } else {
    likes = apify_post.numLikes || apify_post.likeCount || apify_post.totalReactionCount || apify_post.engagement?.likes || 0;
  }
  const comments = apify_post.numComments || apify_post.commentCount || 0;
  const shares = apify_post.numShares || apify_post.repostCount || 0;
  const impressions = apify_post.numImpressions || apify_post.totalImpressionCount || 0;
  const engagement_rate = impressions > 0 ? ((likes + comments + shares) / impressions) : 0;

  const dt = new Date(apify_post.createdAt || apify_post.postedAt || Date.now());
  const col = new Date(dt.getTime() - 5 * 60 * 60 * 1000);

  metricas.push({ json: {
    post_id,
    tema: pub.id || '',
    tono: pub.tono || '',
    area: pub.area || '',
    hora_colombia: col.toISOString().split('T')[1].substring(0, 5),
    fecha: col.toISOString().split('T')[0],
    likes, comments, shares, impressions, engagement_rate
  }});
}
if (metricas.length === 0) return [{ json: { sin_metricas: true } }];
return metricas;

const metricas = items.filter(i => !i.json.sin_metricas).map(i => i.json);
if (metricas.length === 0) return [{ json: { sin_alertas: true } }];

const ers = metricas.map(m => m.engagement_rate || 0).filter(e => e > 0).sort((a,b) => a-b);
if (ers.length === 0) return [{ json: { sin_alertas: true } }];

const promedio = ers.reduce((a,b) => a+b, 0) / ers.length;
const alertas = [];

metricas.forEach(m => {
  const er = m.engagement_rate || 0;
  if (er > promedio * 2.5 && er > 0.02) {
    alertas.push({ tipo: 'exito', post_id: m.post_id, er: (er*100).toFixed(2), 
      tema: m.tema, mensaje: `🏆 Post con ER excepcional: ${(er*100).toFixed(2)}% (${(er/promedio).toFixed(1)}x el promedio)` });
  } else if (er > 0 && er < promedio * 0.3) {
    alertas.push({ tipo: 'bajo', post_id: m.post_id, er: (er*100).toFixed(2),
      tema: m.tema, mensaje: `⚠️ Post con ER muy bajo: ${(er*100).toFixed(2)}% (${(er/promedio).toFixed(2)}x el promedio)` });
  }
});

return [{ json: { alertas, total_metricas: metricas.length, promedio_er: (promedio*100).toFixed(3), tiene_alertas: alertas.length > 0 } }];

