const raw = $json.message?.content || $json.choices?.[0]?.message?.content || $json.content || '';
if (!raw) throw new Error('IA no devolvió contenido');

let limpio = raw.trim()
  .replace(/^```json\s*/i, '').replace(/```$/g, '')
  .replace(/^```\s*/i, '').trim();

const thinkMatch = limpio.match(/<\/think>\s*([\s\S]*)/);
if (thinkMatch) limpio = thinkMatch[1].trim();

let parsed;

// Intento 1: JSON directo
try { parsed = JSON.parse(limpio); }
catch(e1) {
  // Intento 2: extraer objeto con regex
  const match = limpio.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); }
    catch(e2) {
      // Intento 3: JSON truncado — intentar reparar cerrando el objeto
      let truncated = match[0];
      // Cerrar string abierto si lo hay, luego cerrar objeto
      const openQuotes = (truncated.match(/(?<!\\\\)"/g) || []).length % 2;
      if (openQuotes === 1) truncated += '"';
      // Contar llaves y cerrar las que falten
      const opens = (truncated.match(/\{/g) || []).length;
      const closes = (truncated.match(/\}/g) || []).length;
      for (let i = 0; i < opens - closes; i++) truncated += '}';
      try { parsed = JSON.parse(truncated); }
      catch(e3) { throw new Error('JSON inválido tras reparación: ' + limpio.substring(0, 300)); }
    }
  } else {
    throw new Error('Sin JSON en respuesta: ' + limpio.substring(0, 300));
  }
}

let post_text = (parsed.post_text || '').trim();
if (!post_text || post_text.length < 100) throw new Error('post_text inválido o muy corto');

post_text = post_text
  .replace(/\r\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const nParrafos = post_text.split('\n\n').filter(p => p.trim()).length;
const tema_data = $('Combinar Contexto').first().json;

return [{ json: {
  ...tema_data,
  post_text,
  hook_type: parsed.hook_type || 'directo',
  imagen_descripcion: parsed.imagen_descripcion || tema_data.tema_nombre || '',
  hashtags: Array.isArray(parsed.hashtags) ? parsed.hashtags : [],
  char_count: post_text.length,
  n_parrafos: nParrafos,
}}];

const data = $json;
const texto = data.post_text || '';
let score = 100;
const problemas = [];

// 1. Longitud
if (texto.length > 2500) { score -= 25; problemas.push(`Largo: ${texto.length} chars`); }
else if (texto.length < 400) { score -= 20; problemas.push(`Corto: ${texto.length} chars`); }

// 2. Frases prohibidas
['en el mundo actual','es fundamental','la clave está en','es importante','cada vez más',
 'sin duda','definitivamente','en resumen','en conclusión'].forEach(f => {
  if (texto.toLowerCase().includes(f)) { score -= 15; problemas.push(`"${f}"`); }
});

// 3. Emojis
if (/\p{Emoji_Presentation}/u.test(texto)) { score -= 20; problemas.push('Emojis'); }

// 4. Signos exclamación
const exc = (texto.match(/!/g) || []).length;
if (exc > 0) { score -= exc * 10; problemas.push(`${exc} exclamaciones`); }

// 5. Metadata
if (/^(tema|tono|tipo|área|area|profundidad|objetivo):/im.test(texto)) {
  score -= 20; problemas.push('Metadata en texto');
}

// 6. Empieza con #
if (texto.trim().startsWith('#')) { score -= 15; problemas.push('Empieza con #'); }

// 7. Párrafos
const parrafos = texto.split('\n\n').filter(p => p.trim().length > 0);
if (parrafos.length < 2) { score -= 15; problemas.push('Texto sin párrafos'); }

score = Math.max(0, score);
return [{ json: {
  ...data,
  calidad_score: score,
  calidad_pasa: score >= 60,
  calidad_problemas: problemas,
  calidad_label: score >= 80 ? '🟢 Bueno' : score >= 60 ? '🟡 Aceptable' : '🔴 Rechazado',
}}];

